import {
  createElement,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type ChangeEvent,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { groupCatalogByProvider } from "../catalog-groups.js";
import { compactPreviewNodesFromSession, previewCompactDrop, sessionIdOf } from "../compact-preview.js";
import { compactButtonStyle, contextChipCopy, windowSurchargeNote } from "../context-panel-ui.js";
import {
  nearestWindowChoice,
  parseFixesSettings,
  patchSessionOverride,
  resolveEffectiveAutoCompact,
  resolveEffectiveWindow,
  type FixesSettings,
  type WindowChoice as StoredWindowChoice,
} from "../fixes-settings.js";

export const name = "dsh-fixes";
export const inject = ["slots", "settingsScope"];

const FIXES_NS = "dsh-fixes";
const PI_AI_NS = "llm-pi-ai";
const WINDOW_CHOICES = [
  { tokens: 100000, label: "100k" },
  { tokens: 200000, label: "200k" },
  { tokens: 500000, label: "500k" },
  { tokens: 1000000, label: "1M" },
] as const;

type WindowChoice = StoredWindowChoice;
type ModelRef = { provider: string; model: string };
type CatalogModel = { provider: string; model: string; label: string };

type SettingsScope<T> = {
  getSnapshot(): { value?: T };
  subscribe(listener: () => void): () => void;
  set(field: string, value: unknown): Promise<void>;
};

type SettingsScopeBinder = {
  bind<T>(spec: { namespace: string; decode?: (section: unknown) => T | undefined }): SettingsScope<T>;
};

type SlotProps = {
  useSession?: (selector: (value: unknown) => unknown) => unknown;
  useInput?: (selector: (value: unknown) => unknown) => unknown;
  useProjection?: (key: string, selector?: (value: unknown) => unknown) => unknown;
  sessionId?: unknown;
  inputActions?: {
    setDraft?: (text: string) => void;
    submit?: () => void;
  };
  command?: (line: string) => unknown;
  commands?: { run?: (...args: unknown[]) => unknown; execute?: (...args: unknown[]) => unknown };
  "commands/run"?: (...args: unknown[]) => unknown;
};

type ClientContext = {
  slots: {
    inject(name: string, register: () => unknown): unknown;
    register(
      meta: {
        name: string;
        id: string;
        order: number;
        label: string;
      },
      render: (props: SlotProps) => unknown,
    ): unknown;
  };
  settingsScope?: SettingsScopeBinder;
  commands?: { run?: (...args: unknown[]) => unknown };
  "commands/run"?: (...args: unknown[]) => unknown;
  get?(name: string): unknown;
};

const DEFAULT_FIXES: FixesSettings = parseFixesSettings(undefined);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function modelKey(provider: string, model: string): string {
  return `${provider}/${model}`;
}

function settingsBinder(ctx: ClientContext): SettingsScopeBinder | undefined {
  if (ctx.settingsScope !== undefined && typeof ctx.settingsScope.bind === "function") {
    return ctx.settingsScope;
  }
  if (typeof ctx.get === "function") {
    const value = ctx.get("settingsScope");
    if (isRecord(value) && typeof value.bind === "function") {
      return value as SettingsScopeBinder;
    }
  }
  return undefined;
}

function catalogFromPiAi(raw: unknown): CatalogModel[] {
  if (!isRecord(raw) || !isRecord(raw.providers)) return [];
  const models: CatalogModel[] = [];
  const seen = new Set<string>();
  for (const [provider, profile] of Object.entries(raw.providers)) {
    if (!isRecord(profile)) continue;
    const list = Array.isArray(profile.models) ? profile.models : [];
    for (const entry of list) {
      if (!isRecord(entry)) continue;
      const model = typeof entry.id === "string" ? entry.id : typeof entry.name === "string" ? entry.name : "";
      if (!model) continue;
      const key = modelKey(provider, model);
      if (seen.has(key)) continue;
      seen.add(key);
      const display = typeof entry.name === "string" && entry.name && entry.name !== model ? entry.name : model;
      models.push({ provider, model, label: display });
    }
  }
  return models;
}

function providerLabelsFromPiAi(raw: unknown): Record<string, string> {
  if (!isRecord(raw) || !isRecord(raw.providers)) return {};
  const labels: Record<string, string> = {};
  for (const [provider, profile] of Object.entries(raw.providers)) {
    if (!isRecord(profile)) continue;
    const named = typeof profile.displayName === "string" ? profile.displayName.trim() : "";
    labels[provider] = named.length > 0 ? named : provider;
  }
  return labels;
}

function finiteTokens(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function catalogContextWindow(raw: unknown, provider: string, model: string): number | undefined {
  if (!isRecord(raw) || !isRecord(raw.providers)) return undefined;
  const profile = raw.providers[provider];
  if (!isRecord(profile)) return undefined;
  let tokens: number | undefined;
  if (Array.isArray(profile.models)) {
    for (const entry of profile.models) {
      if (!isRecord(entry)) continue;
      const id = typeof entry.id === "string" ? entry.id : typeof entry.name === "string" ? entry.name : "";
      if (id !== model) continue;
      const window = finiteTokens(entry.contextWindow);
      if (window !== undefined) tokens = window;
    }
  }
  const overrides = profile.modelOverrides;
  if (isRecord(overrides) && isRecord(overrides[model])) {
    const window = finiteTokens(overrides[model].contextWindow);
    if (window !== undefined) tokens = window;
  }
  return tokens;
}

function selectedWindowTokens(stored: WindowChoice | undefined, catalogTokens: number | undefined): WindowChoice | undefined {
  if (stored !== undefined) return stored;
  if (catalogTokens !== undefined) return nearestWindowChoice(catalogTokens);
  return undefined;
}

function lookupCommandsRun(source: unknown): ((...args: unknown[]) => unknown) | undefined {
  if (!isRecord(source)) return undefined;
  const direct = source["commands/run"];
  if (typeof direct === "function") return direct.bind(source) as (...args: unknown[]) => unknown;
  const commands = source.commands;
  if (isRecord(commands) && typeof commands.run === "function") {
    return commands.run.bind(commands) as (...args: unknown[]) => unknown;
  }
  return undefined;
}

function findCommandsRun(ctx: ClientContext, props: SlotProps): ((...args: unknown[]) => unknown) | undefined {
  const fromGet = typeof ctx.get === "function" ? ctx.get("commands") : undefined;
  const fromNamed = typeof ctx.get === "function" ? ctx.get("commands/run") : undefined;
  if (typeof fromNamed === "function") return fromNamed as (...args: unknown[]) => unknown;
  return lookupCommandsRun(props) ?? lookupCommandsRun(ctx) ?? lookupCommandsRun(fromGet);
}

function compactErrorText(reason: unknown): string {
  if (!(reason instanceof Error)) return String(reason);
  const generic = /could not produce|useful summary/i.test(reason.message);
  const cause = reason.cause instanceof Error ? reason.cause.message : typeof reason.cause === "string" ? reason.cause : undefined;
  if (generic && cause) return cause;
  return reason.message;
}

function resultErrorText(result: unknown): string {
  if (!isRecord(result)) return "";
  if (result.ok === false && typeof result.error === "string") return result.error;
  if (result.kind === "error" && typeof result.text === "string") return result.text;
  if (isRecord(result.result) && result.result.kind === "error" && typeof result.result.text === "string") {
    return result.result.text;
  }
  return "";
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  return isRecord(value) ? value : undefined;
}

function readModelPair(value: unknown): ModelRef | undefined {
  const rec = asRecord(value);
  if (rec === undefined) return undefined;
  const provider = rec.provider;
  const model = rec.model;
  if (typeof provider === "string" && provider.length > 0 && typeof model === "string" && model.length > 0) {
    return { provider, model };
  }
  return undefined;
}

function modelFromSelection(value: unknown): ModelRef | undefined {
  const rec = asRecord(value);
  if (rec === undefined) return undefined;
  return readModelPair(rec.next)
    ?? readModelPair(rec.lastUsed)
    ?? readModelPair(rec.current)
    ?? readModelPair(rec.config)
    ?? readModelPair(rec);
}

function useScopeValue<T>(scope: SettingsScope<T> | undefined, fallback: T): T {
  return useSyncExternalStore(
    (onStoreChange) => {
      if (scope === undefined) return () => undefined;
      return scope.subscribe(onStoreChange);
    },
    () => scope?.getSnapshot().value ?? fallback,
    () => fallback,
  );
}

const chipStyle: CSSProperties = {
  display: "inline-flex",
  alignItems: "center",
  gap: 6,
  height: 28,
  padding: "0 10px",
  border: "0.5px solid var(--dsw-alias-border-l3, rgba(127,127,127,0.35))",
  borderRadius: 8,
  background: "var(--dsw-alias-interactive-bg-idle, transparent)",
  color: "var(--dsw-alias-label-primary, inherit)",
  font: "inherit",
  fontSize: 12,
  lineHeight: "20px",
  cursor: "pointer",
  whiteSpace: "nowrap",
  flexShrink: 0,
};

const popoverStyle: CSSProperties = {
  position: "fixed",
  zIndex: 10000,
  minWidth: 280,
  padding: 12,
  display: "flex",
  flexDirection: "column",
  gap: 12,
  borderRadius: 12,
  border: "0.5px solid var(--dsw-alias-border-l4, rgba(127,127,127,0.28))",
  background: "var(--dsw-alias-bg-layer-3, var(--dsw-alias-bg-layer-1, #1c1c1c))",
  color: "var(--dsw-alias-label-primary, inherit)",
  boxShadow: "0 8px 24px rgba(0,0,0,0.28)",
  pointerEvents: "auto",
};

const rowStyle: CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: 6,
};

const labelStyle: CSSProperties = {
  fontSize: 12,
  fontWeight: 600,
  color: "var(--dsw-alias-label-secondary, inherit)",
};

const choiceRowStyle: CSSProperties = {
  display: "flex",
  gap: 6,
};

function choiceStyle(active: boolean, disabled: boolean): CSSProperties {
  return {
    flex: 1,
    height: 28,
    border: active
      ? "0.5px solid var(--dsw-alias-state-business-primary, #3b82f6)"
      : "0.5px solid var(--dsw-alias-border-l3, rgba(127,127,127,0.35))",
    borderRadius: 8,
    background: active
      ? "var(--dsw-alias-interactive-bg-selected, rgba(59,130,246,0.16))"
      : "transparent",
    color: "var(--dsw-alias-label-primary, inherit)",
    font: "inherit",
    fontSize: 12,
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.5 : 1,
  };
}

const selectStyle: CSSProperties = {
  height: 30,
  borderRadius: 8,
  border: "0.5px solid var(--dsw-alias-border-l3, rgba(127,127,127,0.35))",
  background: "var(--dsw-alias-bg-layer-1, transparent)",
  color: "inherit",
  font: "inherit",
  fontSize: 12,
  padding: "0 8px",
};

const compactStyle: CSSProperties = {
  height: 32,
  borderRadius: 8,
  border: "0.5px solid transparent",
  font: "inherit",
  fontSize: 12,
};

const errorStyle: CSSProperties = {
  fontSize: 11,
  color: "var(--dsw-alias-state-error-primary, #f87171)",
  margin: 0,
};

const noteStyle: CSSProperties = {
  fontSize: 11,
  opacity: 0.72,
  margin: 0,
  lineHeight: "16px",
};

function checkboxRow(
  label: string,
  checked: boolean,
  disabled: boolean,
  onChange: (next: boolean) => void,
): ReturnType<typeof createElement> {
  return createElement(
    "label",
    {
      style: {
        display: "flex",
        alignItems: "center",
        gap: 6,
        fontSize: 12,
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? "not-allowed" : "pointer",
      },
    },
    createElement("input", {
      type: "checkbox",
      checked,
      disabled,
      onChange: (event: ChangeEvent<HTMLInputElement>) => onChange(event.currentTarget.checked),
    }),
    label,
  );
}

export function apply(ctx: ClientContext): void {
  const binder = settingsBinder(ctx);
  const fixesScope = binder?.bind({ namespace: FIXES_NS, decode: parseFixesSettings });
  const piAiScope = binder?.bind({ namespace: PI_AI_NS });
  const defaultModelScope = binder?.bind({ namespace: "agent-default-model" });

  function ContextPanel(props: SlotProps) {
    const selection = typeof props.useProjection === "function"
      ? props.useProjection("modelSelection", (value) => value)
      : undefined;
    const defaultModel = useScopeValue<unknown>(defaultModelScope, undefined);
    const current = modelFromSelection(selection) ?? readModelPair(defaultModel);
    const sessionSnapshot = typeof props.useSession === "function" ? props.useSession((value) => value) : undefined;
    const running = isRecord(sessionSnapshot) && sessionSnapshot.running === true;
    const sessionId = sessionIdOf(props.sessionId) ?? sessionIdOf(sessionSnapshot);
    const draft = typeof props.useInput === "function"
      ? String(props.useInput((value) => (isRecord(value) && typeof value.draft === "string" ? value.draft : "")) ?? "")
      : "";

    const fixes = useScopeValue(fixesScope, DEFAULT_FIXES);
    const piAi = useScopeValue<unknown>(piAiScope, undefined);
    const catalog = catalogFromPiAi(piAi);
    const catalogGroups = groupCatalogByProvider(catalog, providerLabelsFromPiAi(piAi));

    const [open, setOpen] = useState(false);
    const [error, setError] = useState("");
    const [compacting, setCompacting] = useState(false);
    const [pressed, setPressed] = useState(false);
    const [previewOpen, setPreviewOpen] = useState(false);
    const [draftPercent, setDraftPercent] = useState<number | null>(null);
    const [popoverPos, setPopoverPos] = useState({ bottom: 72, left: 16 });
    const rootRef = useRef<HTMLDivElement | null>(null);
    const popoverRef = useRef<HTMLDivElement | null>(null);
    const savedDraftRef = useRef<string | null>(null);
    const sawRunningRef = useRef(false);
    const setDraftRef = useRef(props.inputActions?.setDraft);

    useEffect(() => {
      if (!open) return;
      const chip = rootRef.current;
      if (chip !== null) {
        const rect = chip.getBoundingClientRect();
        setPopoverPos({
          bottom: Math.max(8, window.innerHeight - rect.top + 8),
          left: Math.max(8, rect.left),
        });
      }
      const onPointer = (event: globalThis.PointerEvent) => {
        const path = typeof event.composedPath === "function" ? event.composedPath() : [];
        const root = rootRef.current;
        const popover = popoverRef.current;
        if (root !== null && path.includes(root)) return;
        if (popover !== null && path.includes(popover)) return;
        if (event.target instanceof Node) {
          if (root !== null && root.contains(event.target)) return;
          if (popover !== null && popover.contains(event.target)) return;
        }
        setOpen(false);
      };
      document.addEventListener("pointerdown", onPointer);
      return () => document.removeEventListener("pointerdown", onPointer);
    }, [open]);

    useEffect(() => {
      setDraftRef.current = props.inputActions?.setDraft;
    }, [props.inputActions?.setDraft]);

    useEffect(() => {
      if (!compacting) {
        sawRunningRef.current = false;
        const saved = savedDraftRef.current;
        if (saved !== null) {
          savedDraftRef.current = null;
          try {
            setDraftRef.current?.(saved);
          } catch {
            // restore is best-effort
          }
        }
        return;
      }
      if (running) {
        sawRunningRef.current = true;
        const saved = savedDraftRef.current;
        if (saved !== null) {
          savedDraftRef.current = null;
          try {
            setDraftRef.current?.(saved);
          } catch {
            // restore is best-effort
          }
        }
        return;
      }
      if (sawRunningRef.current) {
        setCompacting(false);
        return;
      }
      const timer = globalThis.setTimeout(() => {
        setCompacting(false);
      }, 2000);
      return () => globalThis.clearTimeout(timer);
    }, [compacting, running]);

    const modelRefKey = current === undefined ? undefined : modelKey(current.provider, current.model);
    const storedWindow = resolveEffectiveWindow(fixes, sessionId, modelRefKey);
    const catalogWindow = current === undefined ? undefined : catalogContextWindow(piAi, current.provider, current.model);
    const selectedWindow = selectedWindowTokens(storedWindow, catalogWindow);
    const surchargeNote = windowSurchargeNote(selectedWindow);
    const sessionWindowOn = sessionId !== undefined && fixes.sessionOverrides[sessionId]?.window !== undefined;
    const sessionAutoOn = sessionId !== undefined && fixes.sessionOverrides[sessionId]?.autoCompactEnabled !== undefined;
    const autoEnabled = resolveEffectiveAutoCompact(fixes, sessionId);
    const previewNodes = compactPreviewNodesFromSession(sessionSnapshot);
    const preview = previewCompactDrop(previewNodes);
    const previewLine = previewNodes.length === 0 ? "暂不可预览" : preview.line;
    const percent = draftPercent ?? Math.round(fixes.thresholdRatio * 100);
    const windowDisabled = false;
    const compactBusy = running || compacting;
    const compactTitle = compacting ? "压缩进行中" : running ? "忙碌" : "压缩当前会话";
    const chipCopy = contextChipCopy(selectedWindow);

    const persistField = (field: string, value: unknown) => {
      if (fixesScope === undefined) {
        setError("settings unavailable");
        return;
      }
      setError("");
      void fixesScope.set(field, value).catch((reason: unknown) => {
        setError(reason instanceof Error ? reason.message : String(reason));
      });
    };

    const persistOverrides = (next: typeof fixes.sessionOverrides) => {
      persistField("sessionOverrides", next);
    };

    const onWindow = (tokens: WindowChoice) => {
      if (sessionWindowOn && sessionId !== undefined) {
        persistOverrides(patchSessionOverride(fixes.sessionOverrides, sessionId, { window: tokens }));
        return;
      }
      if (current === undefined) {
        setError("无法解析当前模型，窗口改不了");
        return;
      }
      persistField("contextWindows", {
        ...fixes.contextWindows,
        [modelKey(current.provider, current.model)]: tokens,
      });
    };

    const onSessionWindowOnly = (only: boolean) => {
      if (sessionId === undefined) return;
      if (only) {
        persistOverrides(
          patchSessionOverride(fixes.sessionOverrides, sessionId, {
            window: selectedWindow ?? 100000,
          }),
        );
        return;
      }
      persistOverrides(patchSessionOverride(fixes.sessionOverrides, sessionId, { window: null }));
    };

    const onAutoEnabled = (enabled: boolean) => {
      if (sessionAutoOn && sessionId !== undefined) {
        persistOverrides(patchSessionOverride(fixes.sessionOverrides, sessionId, { autoCompactEnabled: enabled }));
        return;
      }
      persistField("autoCompactEnabled", enabled);
    };

    const onSessionAutoOnly = (only: boolean) => {
      if (sessionId === undefined) return;
      if (only) {
        persistOverrides(
          patchSessionOverride(fixes.sessionOverrides, sessionId, {
            autoCompactEnabled: resolveEffectiveAutoCompact(fixes, undefined),
          }),
        );
        return;
      }
      persistOverrides(patchSessionOverride(fixes.sessionOverrides, sessionId, { autoCompactEnabled: null }));
    };

    const onSummarizer = (value: string) => {
      if (value === "") {
        persistField("summarization", null);
        return;
      }
      const index = value.indexOf("/");
      if (index <= 0) return;
      persistField("summarization", { provider: value.slice(0, index), model: value.slice(index + 1) });
    };

    const commitThreshold = (raw: string) => {
      const next = Number(raw);
      setDraftPercent(null);
      if (!Number.isFinite(next)) return;
      persistField("thresholdRatio", next / 100);
    };

    const onCompact = () => {
      setError("正在压缩…");
      if (compacting) return;
      const actions = props.inputActions;
      const setDraft = actions?.setDraft;
      const submit = actions?.submit;
      if (typeof setDraft !== "function" || typeof submit !== "function") {
        setError("当前输入框没有 submit，请在输入框手动输入 /compact 回车");
        return;
      }
      const saved = draft;
      savedDraftRef.current = saved;
      setCompacting(true);
      try {
        setDraft("/compact");
      } catch (reason: unknown) {
        savedDraftRef.current = null;
        setError(compactErrorText(reason));
        setCompacting(false);
        return;
      }
      globalThis.requestAnimationFrame(() => {
        globalThis.requestAnimationFrame(() => {
          try {
            submit();
            setError("已提交 /compact");
          } catch (reason: unknown) {
            setError(compactErrorText(reason));
            setCompacting(false);
            try {
              setDraft(saved);
            } catch {
              // restore is best-effort
            }
          }
        });
      });
    };

    const summarizerValue = fixes.summarization === null ? "" : modelKey(fixes.summarization.provider, fixes.summarization.model);

    return createElement(
      "div",
      { ref: rootRef, style: { position: "relative", display: "inline-flex", flexShrink: 0 } },
      createElement(
        "button",
        {
          type: "button",
          style: chipStyle,
          title: chipCopy.title,
          "aria-label": chipCopy.title,
          "aria-expanded": open,
          "aria-haspopup": "dialog",
          onClick: () => setOpen((value) => !value),
        },
        chipCopy.label,
      ),
      open
        ? createElement(
            "div",
            {
              ref: popoverRef,
              role: "dialog",
              style: { ...popoverStyle, bottom: popoverPos.bottom, left: popoverPos.left },
              onPointerDown: (event: PointerEvent<HTMLDivElement>) => {
                event.stopPropagation();
              },
            },
            createElement(
              "div",
              { style: rowStyle },
              createElement("div", { style: labelStyle }, "上下文"),
              createElement(
                "div",
                { style: choiceRowStyle },
                ...WINDOW_CHOICES.map((choice) =>
                  createElement(
                    "button",
                    {
                      key: choice.label,
                      type: "button",
                      disabled: windowDisabled,
                      title: windowDisabled ? "当前对话模型未知" : choice.label,
                      style: choiceStyle(selectedWindow === choice.tokens, windowDisabled),
                      onClick: () => onWindow(choice.tokens),
                    },
                    choice.label,
                  ),
                ),
              ),
              surchargeNote
                ? createElement(
                    "p",
                    {
                      style: {
                        fontSize: 11,
                        color: "var(--dsw-alias-state-warning-primary, #f59e0b)",
                        margin: 0,
                        lineHeight: "16px",
                      },
                    },
                    surchargeNote,
                  )
                : null,
              checkboxRow(
                "仅当前会话",
                sessionWindowOn,
                sessionId === undefined,
                onSessionWindowOnly,
              ),
            ),
            createElement(
              "div",
              { style: rowStyle },
              createElement("label", { style: labelStyle }, "压缩模型"),
              createElement(
                "select",
                {
                  style: selectStyle,
                  value: summarizerValue,
                  onChange: (event: ChangeEvent<HTMLSelectElement>) => onSummarizer(event.target.value),
                },
                createElement("option", { value: "" }, "当前对话模型"),
                ...catalogGroups.map((group) =>
                  createElement(
                    "optgroup",
                    { key: group.provider, label: group.label },
                    ...group.models.map((entry) =>
                      createElement(
                        "option",
                        { key: modelKey(entry.provider, entry.model), value: modelKey(entry.provider, entry.model) },
                        entry.label,
                      ),
                    ),
                  ),
                ),
              ),
            ),
            createElement(
              "div",
              { style: rowStyle },
              createElement("label", { style: labelStyle }, "自动压缩"),
              checkboxRow("启用自动压缩", autoEnabled, false, onAutoEnabled),
              checkboxRow("仅当前会话", sessionAutoOn, sessionId === undefined, onSessionAutoOnly),
              createElement("input", {
                type: "range",
                min: 20,
                max: 90,
                step: 5,
                value: percent,
                disabled: !autoEnabled,
                onChange: (event: ChangeEvent<HTMLInputElement>) => {
                  setDraftPercent(Number(event.currentTarget.value));
                },
                onPointerUp: (event: PointerEvent<HTMLInputElement>) => {
                  commitThreshold(event.currentTarget.value);
                },
                onKeyUp: (event: KeyboardEvent<HTMLInputElement>) => {
                  commitThreshold(event.currentTarget.value);
                },
              }),
              createElement(
                "div",
                { style: { fontSize: 12, opacity: autoEnabled ? 1 : 0.5 } },
                autoEnabled ? `用到 ${percent}% 时压缩` : "已关闭自动压缩",
              ),
            ),
            createElement(
              "div",
              { style: rowStyle },
              createElement(
                "button",
                {
                  type: "button",
                  disabled: preview.count === 0,
                  title: previewLine,
                  style: {
                    ...noteStyle,
                    background: "transparent",
                    border: 0,
                    padding: 0,
                    color: "inherit",
                    font: "inherit",
                    textAlign: "left",
                    cursor: preview.count === 0 ? "default" : "pointer",
                  },
                  onClick: () => {
                    if (preview.count === 0) return;
                    setPreviewOpen((value) => !value);
                  },
                },
                previewLine,
              ),
              previewOpen && preview.count > 0
                ? createElement(
                    "div",
                    { style: { display: "flex", flexDirection: "column", gap: 4, maxHeight: 160, overflow: "auto" } },
                    ...preview.dropped.map((item) =>
                      createElement(
                        "div",
                        { key: String(item.seq), style: { fontSize: 11, lineHeight: "16px" } },
                        createElement("strong", null, item.title),
                        item.excerpt ? ` · ${item.excerpt}` : "",
                      ),
                    ),
                  )
                : null,
            ),
            createElement(
              "button",
              {
                type: "button",
                style: { ...compactStyle, ...compactButtonStyle({ pressed, busy: compactBusy }) },
                title: compactTitle,
                onPointerDown: () => setPressed(true),
                onPointerUp: () => setPressed(false),
                onPointerLeave: () => setPressed(false),
                onPointerCancel: () => setPressed(false),
                onClick: () => {
                  onCompact();
                },
              },
              compacting ? "压缩中…" : "压缩上下文",
            ),
            createElement(
              "p",
              { style: noteStyle },
              "已爆仓的旧会话要先压缩；只改窗口不会缩短已经超长的历史。",
            ),
            error ? createElement("p", { style: errorStyle }, error) : null,
          )
        : null,
    );
  }

  ctx.slots.inject("conversation.input.right", function () {
    return ctx.slots.register(
      {
        name: "conversation.input.right",
        id: "dsh-fixes-context",
        order: 0,
        label: "Context",
      },
      function (props) {
        return createElement(ContextPanel, props);
      },
    );
  });
}
